package turbo.raid;
import java.awt.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;import javax.swing.*;import com.google.gson.*;import net.runelite.api.*;import net.runelite.api.coords.WorldPoint;import net.runelite.client.callback.ClientThread;
/** Shared setup source, separately compiled into each raid module. No static raid state. */
public final class RaidSetup implements AutoCloseable {
 private static final int MAX_BYTES=4*1024*1024;private final String raid;private final Path root;private final Client client;private final ClientThread thread;private final Supplier<String> gear;private final java.util.function.Consumer<String> status;private JDialog dialog;private JTextArea editor;private JsonObject data;private volatile boolean saving;
 public RaidSetup(String raid,Path root,Client client,ClientThread thread,Supplier<String> gear,java.util.function.Consumer<String> status){if(!raid.equals("toa")&&!raid.equals("tob"))throw new IllegalArgumentException("Unknown raid");this.raid=raid;this.root=root;this.client=client;this.thread=thread;this.gear=gear;this.status=status;}
 public static JsonObject validate(String raid,String text){if(text.getBytes(StandardCharsets.UTF_8).length>MAX_BYTES)throw new IllegalArgumentException("Instance data exceeds 4 MB");JsonObject data=new JsonParser().parse(text).getAsJsonObject();if(!data.has("schema")||!("turbo-"+raid+"-setup-v1").equals(data.get("schema").getAsString()))throw new IllegalArgumentException("Choose "+raid.toUpperCase(Locale.ROOT)+" instance data; other raid profiles are kept separate.");if(data.has("raid")&&!raid.equals(data.get("raid").getAsString()))throw new IllegalArgumentException("Instance data belongs to a different raid");data.addProperty("raid",raid);if(data.has("combatImplemented")&&data.get("combatImplemented").getAsBoolean())throw new IllegalArgumentException("Combat logic is not implemented for this raid yet.");if(!data.has("observedGear")||!data.get("observedGear").isJsonObject())throw new IllegalArgumentException("Instance data needs observedGear");JsonObject gear=data.getAsJsonObject("observedGear");if(gear.size()>4)throw new IllegalArgumentException("Too many gear styles");for(Map.Entry<String,JsonElement> e:gear.entrySet()){if(!Arrays.asList("MAGIC","MELEE","RANGED","SPEC").contains(e.getKey())||!e.getValue().isJsonArray()||e.getValue().getAsJsonArray().size()>14)throw new IllegalArgumentException("Invalid gear style or size");for(JsonElement id:e.getValue().getAsJsonArray())if(id.getAsInt()<=0)throw new IllegalArgumentException("Gear item IDs must be positive");}data.addProperty("combatImplemented",false);return data;}
 public static void write(Path target,String raid,String text)throws java.io.IOException{String json=new GsonBuilder().setPrettyPrinting().create().toJson(validate(raid,text));Path destination=target.toAbsolutePath();Files.createDirectories(destination.getParent());Path temp=Files.createTempFile(destination.getParent(),"raid-setup-",".tmp");try{Files.writeString(temp,json,StandardCharsets.UTF_8);try{Files.move(temp,destination,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,destination,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}}
 private String schema(){return "turbo-"+raid+"-setup-v1";}
 public synchronized JsonObject snapshot(){return data==null?null:data.deepCopy();}
 public Window window(Frame owner){if(dialog!=null&&dialog.isDisplayable())return dialog;dialog=new JDialog((Frame)null,raid.equals("toa")?"AI TOA Fighter - settings":"TOB AI Fighter - settings",false);dialog.setDefaultCloseOperation(WindowConstants.HIDE_ON_CLOSE);JPanel panel=new JPanel(new BorderLayout(8,8));panel.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));JPanel buttons=new JPanel(new GridLayout(1,3,8,0));JButton load=new JButton("Load instance data"),save=new JButton("Save instance data"),restore=new JButton("Load pre-saved data");buttons.add(load);buttons.add(save);buttons.add(restore);JTextArea guide=new JTextArea("Load instance data captures room, NPC and gear candidates.\nSave instance data applies your edits and saves this raid only.\nLoad pre-saved data restores a saved setup. Combat logic remains pending.");guide.setLineWrap(true);guide.setWrapStyleWord(true);guide.setEditable(false);guide.setOpaque(false);guide.setRows(4);JPanel top=new JPanel(new BorderLayout(8,8));top.add(buttons,BorderLayout.NORTH);top.add(guide,BorderLayout.CENTER);panel.add(top,BorderLayout.NORTH);editor=new JTextArea(data==null?"Load instance data to populate this raid's setup.":new GsonBuilder().setPrettyPrinting().create().toJson(data),20,75);panel.add(new JScrollPane(editor),BorderLayout.CENTER);JLabel message=new JLabel("No combat inputs are sent by setup controls.");panel.add(message,BorderLayout.SOUTH);load.addActionListener(e->thread.invoke(()->{try{JsonObject candidate=loadCandidate();synchronized(this){data=candidate;}show(candidate);status.accept("Instance data loaded for "+raid.toUpperCase(Locale.ROOT)+". Combat logic pending.");SwingUtilities.invokeLater(()->message.setText("Room and available gear loaded. Verify the style presets for this raid."));}catch(Exception error){failed(error,message);}}));
  save.addActionListener(e->{if(saving)return;final String text=editor.getText();try{JsonObject next=validate(raid,text);synchronized(this){data=next;}saving=true;CompletableFuture.runAsync(()->{try{write(root.resolve("instance-data.json"),raid,text);status.accept("Saved "+raid.toUpperCase(Locale.ROOT)+" instance data.");SwingUtilities.invokeLater(()->message.setText("Saved instance-data.json in this raid's own data folder."));}catch(Exception error){failed(error,message);}finally{saving=false;}});}catch(Exception error){failed(error,message);}});
  restore.addActionListener(e->{JFileChooser chooser=new JFileChooser(root.toFile());chooser.setDialogTitle("Load "+raid.toUpperCase(Locale.ROOT)+" pre-saved data");chooser.setSelectedFile(root.resolve("instance-data.json").toFile());if(chooser.showOpenDialog(dialog)!=JFileChooser.APPROVE_OPTION)return;Path path=chooser.getSelectedFile().toPath();CompletableFuture.runAsync(()->{try{if(Files.size(path)>MAX_BYTES)throw new IllegalArgumentException("Instance data exceeds 4 MB");JsonObject next=validate(raid,Files.readString(path));synchronized(this){data=next;}show(next);status.accept("Loaded pre-saved "+raid.toUpperCase(Locale.ROOT)+" instance data.");SwingUtilities.invokeLater(()->message.setText("Pre-saved instance data applied to this raid only."));}catch(Exception error){failed(error,message);}});});dialog.setContentPane(panel);dialog.pack();dialog.setLocationRelativeTo(owner);return dialog;}
 private void show(JsonObject value){String text=new GsonBuilder().setPrettyPrinting().create().toJson(value);SwingUtilities.invokeLater(()->{if(editor!=null){editor.setText(text);editor.setCaretPosition(0);}});}
 private void failed(Exception error,JLabel label){String message=error.getMessage()==null?error.getClass().getSimpleName():error.getMessage();status.accept("Instance setup: "+message);SwingUtilities.invokeLater(()->{label.setText(message);JOptionPane.showMessageDialog(dialog,message,"Instance data",JOptionPane.INFORMATION_MESSAGE);});}
 private JsonObject loadCandidate()throws Exception{Path candidate=root.resolve("observed-candidate.json");if(Files.isRegularFile(candidate)){if(Files.size(candidate)>MAX_BYTES)throw new IllegalArgumentException("Candidates exceed 4 MB");return validate(raid,Files.readString(candidate));}Player self=client.getLocalPlayer();if(client.getGameState()!=GameState.LOGGED_IN||self==null||self.getLocalLocation()==null)throw new IllegalStateException("Log into Orion in this raid's lobby or room before loading instance data.");JsonObject result=new JsonObject();result.addProperty("schema",schema());result.addProperty("raid",raid);result.addProperty("observedAt",Instant.now().toString());result.addProperty("combatImplemented",false);JsonObject presets=new JsonParser().parse(gear.get()).getAsJsonObject();result.add("observedGear",presets);result.add("currentEquipment",items(client.getItemContainer(InventoryID.EQUIPMENT)));result.add("inventory",items(client.getItemContainer(InventoryID.INVENTORY)));WorldPoint pos=WorldPoint.fromLocalInstance(client,self.getLocalLocation());if(pos==null)throw new IllegalStateException("Wait for the room to finish loading.");JsonArray room=new JsonArray();room.add(pos.getX());room.add(pos.getY());room.add(pos.getPlane());result.add("roomPosition",room);JsonArray npcs=new JsonArray();for(NPC npc:client.getNpcs())if(npc.getWorldLocation().distanceTo(self.getWorldLocation())<=32&&npcs.size()<128)npcs.add(npc.getId());result.add("npcCandidates",npcs);result.add("mechanics",new JsonObject());return validate(raid,result.toString());}
 private JsonArray items(ItemContainer bag){JsonArray result=new JsonArray();if(bag!=null)for(Item item:bag.getItems())if(item!=null&&item.getId()>0){JsonArray slot=new JsonArray();slot.add(item.getId());slot.add(item.getQuantity());result.add(slot);}return result;}
 public void close(){SwingUtilities.invokeLater(()->{if(dialog!=null)dialog.dispose();dialog=null;editor=null;});synchronized(this){data=null;}}
}
